Tool "github.list_issues" in the github box
Posture: runs immediately
Title (server-provided): "List issues"
What the server says it does:
    List issues in a GitHub repository. For pagination, use the 'endCursor' from the previous response's 'pageInfo' in the 'after' parameter.

Input schema (JSON Schema):
    {
      "type": "object",
      "properties": {
        "after": {
          "type": "string",
          "description": "Cursor for pagination. Use the cursor from the previous response."
        },
        "direction": {
          "type": "string",
          "description": "Order direction. If provided, the 'orderBy' also needs to be provided.",
          "enum": [
            "ASC",
            "DESC"
          ]
        },
        "field_filters": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "field_name": {
                "type": "string",
                "description": "Name of the custom field (e.g. \"Priority\"). Case-insensitive."
              },
              "value": {
                "type": "string",
                "description": "Value to filter on. For single-select fields, the option name (e.g. \"P1\"). For dates, YYYY-MM-DD. For numbers, the numeric value as a string. For text, the text value."
              }
            },
            "required": [
              "field_name",
              "value"
            ]
          },
          "description": "Filter by custom issue field values. Each entry takes a field_name and a value; the server looks up the field and coerces the value to its type (single-select option name, text, number, or YYYY-MM-DD date)."
        },
        "fields": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "number",
              "title",
              "body",
              "state",
              "user",
              "labels",
              "assignees",
              "comments",
              "created_at",
              "updated_at",
              "field_values"
            ]
          },
          "description": "Subset of fields to return for each issue. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' and 'field_values' in particular drops the largest per-result data."
        },
        "labels": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Filter by labels"
        },
        "orderBy": {
          "type": "string",
          "description": "Order issues by field. If provided, the 'direction' also needs to be provided.",
          "enum": [
            "CREATED_AT",
            "UPDATED_AT",
            "COMMENTS"
          ]
        },
        "owner": {
          "type": "string",
          "description": "Repository owner"
        },
        "perPage": {
          "type": "number",
          "description": "Results per page for pagination (min 1, max 100)",
          "minimum": 1,
          "maximum": 100
        },
        "repo": {
          "type": "string",
          "description": "Repository name"
        },
        "since": {
          "type": "string",
          "description": "Filter by date (ISO 8601 timestamp)"
        },
        "state": {
          "type": "string",
          "description": "Filter by state, by default both open and closed issues are returned when not provided",
          "enum": [
            "OPEN",
            "CLOSED"
          ]
        }
      },
      "required": [
        "owner",
        "repo"
      ]
    }

Output schema: none declared — the result may be a structured object or text (sometimes JSON text, which a machine receives as a string). Before a machine reads its fields, call it once with call_tool and look at the result: event.result is that same value (call_tool prints an object as indented JSON, text as it is).

TypeScript (as in projection://types/tools.d.ts):
    /** Input for tool "github.list_issues". */
    export type github_ListIssuesInput = {
      /** Cursor for pagination. Use the cursor from the previous response. */
      after?: string;
      /** Order direction. If provided, the 'orderBy' also needs to be provided. */
      direction?: "ASC" | "DESC";
      /** Filter by custom issue field values. Each entry takes a field_name and a value; the server looks up the field and coerces the value to its type (single-select option name, text, number, or YYYY-MM-DD date). */
      field_filters?: Array<{
        /** Name of the custom field (e.g. "Priority"). Case-insensitive. */
        field_name: string;
        /** Value to filter on. For single-select fields, the option name (e.g. "P1"). For dates, YYYY-MM-DD. For numbers, the numeric value as a string. For text, the text value. */
        value: string;
      }>;
      /** Subset of fields to return for each issue. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' and 'field_values' in particular drops the largest per-result data. */
      fields?: Array<"number" | "title" | "body" | "state" | "user" | "labels" | "assignees" | "comments" | "created_at" | "updated_at" | "field_values">;
      /** Filter by labels */
      labels?: string[];
      /** Order issues by field. If provided, the 'direction' also needs to be provided. */
      orderBy?: "CREATED_AT" | "UPDATED_AT" | "COMMENTS";
      /** Repository owner */
      owner: string;
      /** Results per page for pagination (min 1, max 100) */
      perPage?: number;
      /** Repository name */
      repo: string;
      /** Filter by date (ISO 8601 timestamp) */
      since?: string;
      /** Filter by state, by default both open and closed issues are returned when not provided */
      state?: "OPEN" | "CLOSED";
    };

    // Member of tools.github:
    /**
     * List issues in a GitHub repository. For pagination, use the 'endCursor' from the previous response's 'pageInfo' in the 'after' parameter.
     *
     * Runs immediately: no user approval required.
     */
    list_issues: (args: github_ListIssuesInput) => Promise<unknown>;

Tool "github.label_write" in the github box
Posture: asks for approval (the server marks this tool destructive)
Title (server-provided): "Write operations on repository labels"
What the server says it does:
    Perform write operations on repository labels. To set labels on issues, use the 'update_issue' tool.

Input schema (JSON Schema):
    {
      "type": "object",
      "properties": {
        "color": {
          "type": "string",
          "description": "Label color as 6-character hex code without '#' prefix (e.g., 'f29513'). Required for 'create', optional for 'update'."
        },
        "description": {
          "type": "string",
          "description": "Label description text. Optional for 'create' and 'update'."
        },
        "method": {
          "type": "string",
          "description": "Operation to perform: 'create', 'update', or 'delete'",
          "enum": [
            "create",
            "update",
            "delete"
          ]
        },
        "name": {
          "type": "string",
          "description": "Label name - required for all operations"
        },
        "new_name": {
          "type": "string",
          "description": "New name for the label (used only with 'update' method to rename)"
        },
        "owner": {
          "type": "string",
          "description": "Repository owner (username or organization name)"
        },
        "repo": {
          "type": "string",
          "description": "Repository name"
        }
      },
      "required": [
        "method",
        "owner",
        "repo",
        "name"
      ]
    }

Output schema: none declared — the result may be a structured object or text (sometimes JSON text, which a machine receives as a string). Do not write code that depends on a result shape you have not seen.

TypeScript (as in projection://types/tools.d.ts):
    /** Input for tool "github.label_write". */
    export type github_LabelWriteInput = {
      /** Label color as 6-character hex code without '#' prefix (e.g., 'f29513'). Required for 'create', optional for 'update'. */
      color?: string;
      /** Label description text. Optional for 'create' and 'update'. */
      description?: string;
      /** Operation to perform: 'create', 'update', or 'delete' */
      method: "create" | "update" | "delete";
      /** Label name - required for all operations */
      name: string;
      /** New name for the label (used only with 'update' method to rename) */
      new_name?: string;
      /** Repository owner (username or organization name) */
      owner: string;
      /** Repository name */
      repo: string;
    };

    // Member of tools.github:
    /**
     * Perform write operations on repository labels. To set labels on issues, use the 'update_issue' tool.
     *
     * Asks for approval: pauses for the user to approve this exact call before it runs. The server marks this tool destructive.
     */
    label_write: (args: github_LabelWriteInput) => Promise<unknown>;

Tool "github.issue_write" in the github box
Posture: asks for approval
Title (server-provided): "Create or update issue/pull request"
What the server says it does:
    Create a new or update an existing issue in a GitHub repository.

Input schema (JSON Schema):
    {
      "type": "object",
      "properties": {
        "assignees": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Usernames to assign to this issue"
        },
        "body": {
          "type": "string",
          "description": "Issue body content"
        },
        "duplicate_of": {
          "type": "number",
          "description": "Issue number that this issue is a duplicate of. Required when state_reason is 'duplicate'."
        },
        "issue_fields": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "delete": {
                "type": "boolean",
                "description": "Set to true to clear this field's current value on the issue. When false or omitted, this property is ignored. Cannot be true when 'value' or 'field_option_name' is provided."
              },
              "field_name": {
                "type": "string",
                "description": "Issue field name (case-insensitive). Must match a field returned by list_issue_fields for this repository or its organization."
              },
              "field_option_name": {
                "type": "string",
                "description": "Option name for single-select fields. Validated against the field's options before the API call. Cannot be combined with 'value' or 'delete: true'."
              },
              "value": {
                "type": [
                  "string",
                  "number",
                  "boolean"
                ],
                "description": "Value to set. Use for text, number, and date fields (date as YYYY-MM-DD). For single-select fields, prefer 'field_option_name' so the option is validated before the API call. Cannot be combined with 'field_option_name' or 'delete: true'."
              }
            },
            "required": [
              "field_name"
            ],
            "additionalProperties": false
          },
          "description": "Issue field values to set or clear. Each item requires 'field_name' and exactly one of 'value', 'field_option_name', or 'delete: true'."
        },
        "issue_number": {
          "type": "number",
          "description": "Issue number to update"
        },
        "labels": {
