import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabel',
  context: {
    owner: 'acme',
    repo: 'widgets',
    cutoffDate: '2026-07-01T00:00:00Z',
    allIssues: [],
    staleIssues: [],
    updates: [],
    updateResults: {},
  },
  initial: 'fetchIssues',
  states: {
    fetchIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'labels', 'updated_at', 'title'],
      }), { id: 'listIssues' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listIssues'),
          target: 'processIssues',
          actions: assign({
            allIssues: ({ event }) => {
              const result = event.result;
              if (typeof result === 'string') {
                const parsed = JSON.parse(result);
                return parsed.issues || [];
              }
              return result.issues || [];
            },
          }),
        },
        TOOL_ERROR: 'error',
      },
    },
    processIssues: {
      always: {
        actions: assign({
          staleIssues: ({ context }) => {
            const cutoff = new Date(context.cutoffDate);
            const stale = context.allIssues.filter(issue => {
              const updatedAt = new Date(issue.updated_at);
              const isStale = updatedAt < cutoff;
              return isStale;
            });
            return stale;
          },
        }),
        target: 'prepareUpdates',
      },
    },
    prepareUpdates: {
      always: {
        target: 'applyLabels',
        actions: assign({
          updates: ({ context }) => {
            return context.staleIssues.map(issue => ({
              issueNumber: issue.number,
              currentLabels: (issue.labels || []).map(l => l.name),
              title: issue.title,
            }));
          },
        }),
      },
    },
    applyLabels: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.updates.forEach((update, index) => {
          const newLabels = [...update.currentLabels];
          if (!newLabels.includes('stale')) {
            newLabels.push('stale');
          }
          enqueue(toolCall('github.issue_write', {
            method: 'update',
            owner: context.owner,
            repo: context.repo,
            issue_number: update.issueNumber,
            labels: newLabels,
          }, { id: `update_${index}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: { status: 'success' },
            }),
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: { status: 'denied' },
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: { status: 'error', error: event.error },
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          Object.keys(context.updateResults).length === context.updates.length,
        target: 'done',
      },
    },
    error: { type: 'final' },
    done: { type: 'final' },
  },
  output: ({ context }) => ({
    staleLabelCount: context.updates.length,
    successCount: Object.values(context.updateResults).filter(r => r.status === 'success').length,
    deniedCount: Object.values(context.updateResults).filter(r => r.status === 'denied').length,
    errorCount: Object.values(context.updateResults).filter(r => r.status === 'error').length,
    issuesUpdated: context.updates.map(u => u.issueNumber),
  }),
});

