    commentedPRs: [],
    skippedPRs: [],
    failedPRs: [],
  },
  initial: 'listingOpenPRs',
  states: {
    listingOpenPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title'],
      })),
      on: {
