    checkingFiles: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.openPRs.forEach((pr, i) => {
          enqueue(
            toolCall('github.pull_request_read', {
              owner: context.owner,
              repo: context.repo,
              pullNumber: pr.number,
              method: 'get_files',
              perPage: 100,
            }, { id: 'check_' + pr.number })
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: event.result,
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: null,
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedChecks = context.openPRs.length;
          const completedChecks = Object.keys(context.fileCheckResults).length;
          return completedChecks === expectedChecks;
        },
        target: 'filteringPRs',
      },
    },
