              body: 'Please add a CHANGELOG entry for the export changes.',
            }, { id: 'comment_' + pr.number })
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commentedPRs: ({ context, event }) => [
              ...context.commentedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skippedPRs: ({ context, event }) => [
              ...context.skippedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failedPRs: ({ context, event }) => [
              ...context.failedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedComments = context.prsToComment.length;
          const completedComments = context.commentedPRs.length + context.skippedPRs.length + context.failedPRs.length;
          return completedComments === expectedComments;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalOpenPRs: context.openPRs.length,
    prsWithExportChanges: context.prsToComment.length,
    commentedPRs: context.commentedPRs,
    skippedPRs: context.skippedPRs,
    failedPRs: context.failedPRs,
  }),
});

