import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnExportPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    openPRs: [],
    filesPerPR: {},
    prsToComment: [],
    commentResults: {},
  },
  initial: 'listingOpenPRs',
  states: {
    listingOpenPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        perPage: 100,
      })),
      on: {
        TOOL_RESULT: {
          target: 'checkingFilesForAllPRs',
          actions: assign({
            openPRs: ({ event }) => {
              console.log('Result type:', typeof event.result, 'Is array:', Array.isArray(event.result));
              return Array.isArray(event.result) ? event.result : [];
            },
          }),
        },
        TOOL_ERROR: { target: 'done' },
      },
    },
    checkingFilesForAllPRs: {
      entry: enqueueActions(({ context, enqueue }) => {
        console.log('About to check files for', context.openPRs.length, 'PRs');
        for (const pr of context.openPRs) {
          enqueue(toolCall('github.pull_request_read', {
            owner: context.owner,
            repo: context.repo,
            pullNumber: pr.number,
            method: 'get_files',
            perPage: 100,
          }, { id: 'files_' + pr.number }));
        }
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            filesPerPR: ({ context, event }) => ({
              ...context.filesPerPR,
              [event.callId]: event.result || [],
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            filesPerPR: ({ context, event }) => ({
              ...context.filesPerPR,
              [event.callId]: [],
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const filesChecked = Object.keys(context.filesPerPR).length;
          const totalPRs = context.openPRs.length;
          console.log('Files checked:', filesChecked, 'Total PRs:', totalPRs);
          return filesChecked === totalPRs;
        },
        target: 'identifyingRelevantPRs',
      },
    },
    identifyingRelevantPRs: {
      entry: assign({
        prsToComment: ({ context }) => {
          const relevant = context.openPRs.filter((pr) => {
            const callId = 'files_' + pr.number;
            const files = context.filesPerPR[callId];
            const hasExport = Array.isArray(files) && files.some((f) => (f.filename || '').startsWith('src/export/'));
            if (hasExport) console.log('PR', pr.number, 'has export changes');
            return hasExport;
          });
          return relevant;
        },
      }),
      always: { target: 'postingComments' },
    },
    postingComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        console.log('Posting comments to', context.prsToComment.length, 'PRs');
        for (const pr of context.prsToComment) {
          enqueue(toolCall('github.add_issue_comment', {
            owner: context.owner,
            repo: context.repo,
            issue_number: pr.number,
            body: 'Please add a CHANGELOG entry for the export changes.',
          }, { id: 'comment_' + pr.number }));
        }
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commentResults: ({ context, event }) => ({
              ...context.commentResults,
              [event.callId]: 'success',
            }),
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            commentResults: ({ context, event }) => ({
              ...context.commentResults,
              [event.callId]: 'denied',
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            commentResults: ({ context, event }) => ({
              ...context.commentResults,
              [event.callId]: 'error',
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const done = Object.keys(context.commentResults).length === context.prsToComment.length;
          console.log('Comments done?', done, Object.keys(context.commentResults).length, 'of', context.prsToComment.length);
          return done;
        },
        target: 'done',
      },
    },
    done: { type: 'final' },
  },
  output: ({ context }) => ({
    totalOpenPRs: context.openPRs.length,
    prsWithExportChanges: context.prsToComment.length,
    prsCommented: context.prsToComment.map(pr => pr.number),
    commentResults: context.commentResults,
  }),
});

