import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnExportPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    openPRs: [],
    prsToComment: [],
    fileCheckResults: {},
    commentedPRs: [],
    skippedPRs: [],
    failedPRs: [],
  },
  initial: 'listingOpenPRs',
  states: {
    listingOpenPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title'],
      })),
      on: {
        TOOL_RESULT: {
          target: 'checkingFiles',
          actions: assign({
            openPRs: ({ event }) => event.result || [],
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            failedPRs: ({ context }) => [...context.failedPRs, 'listing'],
          }),
        },
      },
    },
    checkingFiles: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.openPRs.forEach((pr, i) => {
          enqueue(
            toolCall('github.pull_request_read', {
              owner: context.owner,
              repo: context.repo,
              pullNumber: pr.number,
              method: 'get_files',
              perPage: 100,
            }, { id: 'check_' + pr.number })
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: event.result,
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: null,
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedChecks = context.openPRs.length;
          const completedChecks = Object.keys(context.fileCheckResults).length;
          return completedChecks === expectedChecks;
        },
        target: 'filteringPRs',
      },
    },
    filteringPRs: {
      entry: assign({
        prsToComment: ({ context }) => {
          return context.openPRs.filter((pr) => {
            const callId = 'check_' + pr.number;
            const files = context.fileCheckResults[callId];

            if (!files || !Array.isArray(files)) {
              return false;
            }

            return files.some((file) => {
              const filename = file.filename || '';
              return filename.startsWith('src/export/');
            });
          });
        },
      }),
      target: 'postingComments',
    },
    postingComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prsToComment.forEach((pr, i) => {
          enqueue(
            toolCall('github.add_issue_comment', {
              owner: context.owner,
              repo: context.repo,
              issue_number: pr.number,
              body: 'Please add a CHANGELOG entry for the export changes.',
            }, { id: 'comment_' + pr.number })
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commentedPRs: ({ context, event }) => [
              ...context.commentedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skippedPRs: ({ context, event }) => [
              ...context.skippedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failedPRs: ({ context, event }) => [
              ...context.failedPRs,
              event.callId.replace('comment_', ''),
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedComments = context.prsToComment.length;
          const completedComments = context.commentedPRs.length + context.skippedPRs.length + context.failedPRs.length;
          return completedComments === expectedComments;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalOpenPRs: context.openPRs.length,
    prsWithExportChanges: context.prsToComment.length,
    commentedPRs: context.commentedPRs,
    skippedPRs: context.skippedPRs,
    failedPRs: context.failedPRs,
  }),
});

