import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'auditLogSync',
  context: {
    shippedOrders: [],
    existingAuditLogs: [],
    missingAuditLogs: [],
    insertedCount: 0,
  },
  initial: 'findShippedOrders',
  states: {
    findShippedOrders: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'orders',
        filter: { status: 'shipped' },
        projection: { _id: 1, orderId: 1, status: 1 },
      }),
      on: {
        TOOL_RESULT: {
          target: 'findExistingAuditLogs',
          actions: assign({
            shippedOrders: ({ event }) => event.result.documents || [],
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
        },
      },
    },
    findExistingAuditLogs: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        filter: { action: 'shipped' },
        projection: { orderId: 1 },
      }),
      on: {
        TOOL_RESULT: {
          target: 'identifyMissing',
          actions: assign({
            existingAuditLogs: ({ event }) => event.result.documents || [],
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
        },
      },
    },
    identifyMissing: {
      type: 'final',
      actions: assign({
        missingAuditLogs: ({ context }) => {
          const existingOrderIds = new Set(
            context.existingAuditLogs.map(log => log.orderId)
          );
          return context.shippedOrders
            .filter(order => !existingOrderIds.has(order.orderId))
            .map(order => ({
              orderId: order.orderId,
              action: 'shipped',
            }));
        },
      }),
      output: ({ context }) => {
        if (context.missingAuditLogs.length === 0) {
          return {
            status: 'complete',
            message: 'All shipped orders already have audit log entries.',
            inserted: 0,
          };
        }
        return {
          status: 'ready_to_insert',
          missingCount: context.missingAuditLogs.length,
          logs: context.missingAuditLogs,
        };
      },
    },
    failed: {
      type: 'final',
      output: ({ context }) => ({
        status: 'error',
        message: 'Failed to retrieve data from database.',
      }),
    },
  },
});

