            const docs = event.output.documents as Array<{ email: string; tier: string; _id: any }>;
            if (docs.length === 0) {
              // Customer doesn't exist, add to missing list
              context.missingEmails.push(context.vipEmails[context.currentIndex]);
            } else {
              // Customer exists, we'll update tier in next step
            }
          }
        },
        onError: () => console.error('Failed to find customer')
      }
    },
    checkCustomerExists: {
      invoke: {
        src: ({ context }) => {
          const email = context.vipEmails[context.currentIndex];
          return toolCall('mongo.find', {
            connectionId: 'preconfigured',
            database: 'shop',
            collection: 'customers',
            filter: { email }
          });
        },
        onDone: {
          target: 'updateCustomerTier',
          actions: ({ event, context }) => {
            const docs = event.output.documents as Array<{ email: string; tier: string; _id: any }>;
            // Store the document count for conditional routing
            context.processedCount = docs.length;
          }
        }
      }
    },
    updateCustomerTier: {
      always: [
        {
          target: 'nextEmail',
          guard: ({ context }) => context.processedCount === 0
        },
        {
          target: 'updateTierCall',
          guard: ({ context }) => context.processedCount > 0
        }
      ]
    },
    updateTierCall: {
      invoke: {
        src: ({ context }) => {
          const email = context.vipEmails[context.currentIndex];
          return toolCall('mongo.update-many', {
            connectionId: 'preconfigured',
            database: 'shop',
            collection: 'customers',
            filter: { email },
            update: { $set: { tier: 'gold' } }
          });
        },
        onDone: 'nextEmail',
        onError: () => console.error('Failed to update customer tier')
      }
    },
    nextEmail: {
      entry: ({ context }) => {
        context.currentIndex++;
        'logProgress'();
      },
      always: {
        target: 'parseEmails'
      }
    },
    writeMissingVips: {
      invoke: {
        src: ({ context }) => {
          if (context.missingEmails.length === 0) {
            // No missing emails, we're done
            return Promise.resolve({ written: 0 });
          }
          const content = context.missingEmails.join('\n') + '\n';
          return toolCall('fs.write_file', {
            path: 'notes/missing-vips.txt',
            content
          });
        },
        onDone: 'complete',
        onError: () => console.error('Failed to write missing-vips.txt')
      }
    },
    complete: {
      type: 'final'
    }
  }
});

