import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

interface Customer {
  _id: any;
  email: string;
  tier: string;
}

interface FindResult {
  documents: Customer[];
  queryResultsCount: number;
  appliedLimits: string[];
}

interface EmailInfo {
  email: string;
  exists: boolean;
}

export default setup({}).createMachine({
  id: 'vip-processor',
  context: {
    vipEmails: [] as string[],
    emailInfo: [] as EmailInfo[],
    missingEmails: [] as string[],
    readCount: 0
  },
  initial: 'readVipFile',
  states: {
    readVipFile: {
      entry: toolCall('fs.read_file', { path: 'notes/vip.txt' }),
      on: {
        TOOL_RESULT: {
          target: 'queryAllCustomers',
          actions: assign({
            vipEmails: ({ event }) => {
              const result = event.result as { content: string };
              const content = result.content;
              return content
                .split('\n')
                .map(line => line.trim())
                .filter(line => line && !line.startsWith('#'));
            }
          })
        },
        TOOL_ERROR: 'failed'
      }
    },
    queryAllCustomers: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, idx) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email }
              },
              { id: 'check' + idx }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            emailInfo: ({ context, event }) => {
              const idx = parseInt(event.callId.replace('check', ''));
              const result = event.result as FindResult;
              const exists = result.documents.length > 0;
              const newInfo = [...context.emailInfo];
              newInfo[idx] = { email: context.vipEmails[idx], exists };
              return newInfo;
            },
            readCount: ({ context }) => context.readCount + 1
          })
        },
        TOOL_ERROR: {
          actions: assign({
            readCount: ({ context }) => context.readCount + 1
          })
        },
        always: {
          guard: ({ context }) => context.readCount === context.vipEmails.length,
          target: 'prepareUpdates'
        }
      }
    },
    prepareUpdates: {
