import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

interface Customer {
  _id: any;
  email: string;
  tier: string;
}

interface FindResult {
  documents: Customer[];
  queryResultsCount: number;
  appliedLimits: string[];
}

interface EmailInfo {
  email: string;
  exists: boolean;
}

export default setup({}).createMachine({
  id: 'vip-processor',
  context: {
    vipEmails: [] as string[],
    emailInfo: [] as EmailInfo[],
    missingEmails: [] as string[],
    responseCount: 0
  },
  initial: 'readVipFile',
  states: {
    readVipFile: {
      entry: toolCall('fs.read_file', { path: 'notes/vip.txt' }),
      on: {
        TOOL_RESULT: {
          target: 'queryAllCustomers',
          actions: assign({
            vipEmails: ({ event }) => {
              const result = event.result as { content: string };
              const content = result.content;
              return content
                .split('\n')
                .map(line => line.trim())
                .filter(line => line && !line.startsWith('#'));
            },
            emailInfo: ({ context }) => context.vipEmails.map(email => ({ email, exists: false }))
          })
        },
        TOOL_ERROR: 'failed'
      }
    },
    queryAllCustomers: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, idx) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email }
              },
              { id: 'check' + idx }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            emailInfo: ({ context, event }) => {
              const idx = parseInt((event.callId as string).replace('check', ''));
              const result = event.result as FindResult;
              const exists = result.documents.length > 0;
              const newInfo = [...context.emailInfo];
              newInfo[idx] = { email: context.vipEmails[idx], exists };
              return newInfo;
            },
            responseCount: ({ context }) => context.responseCount + 1
          })
        },
        TOOL_ERROR: {
          actions: assign({
            responseCount: ({ context }) => context.responseCount + 1
          })
        }
      },
      always: {
        guard: ({ context }) => context.responseCount === context.vipEmails.length,
        target: 'prepareUpdates'
      }
    },
    prepareUpdates: {
      entry: assign({
        missingEmails: ({ context }) => context.emailInfo
          .filter(info => !info.exists)
          .map(info => info.email)
      }),
      always: 'executeUpdates'
    },
    executeUpdates: {
      always: [
        {
          guard: ({ context }) => 
            context.emailInfo.filter(info => info.exists).length === 0,
          target: 'writeMissingVips'
        },
        {
          target: 'updateAllTiers'
        }
      ]
    },
    updateAllTiers: {
      entry: enqueueActions(({ context, enqueue }) => {
        const existingCustomers = context.emailInfo.filter(info => info.exists);
        existingCustomers.forEach((info, idx) => {
          enqueue(
            toolCall(
              'mongo.update-many',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email: info.email },
                update: { $set: { tier: 'gold' } }
              },
              { id: 'update' + idx }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {},
        TOOL_DENIED: {},
        TOOL_ERROR: {}
      },
      always: {
        target: 'writeMissingVips'
      }
    },
    writeMissingVips: {
      always: [
        {
          guard: ({ context }) => context.missingEmails.length === 0,
          target: 'done'
        },
        {
          target: 'writeFile'
        }
      ]
    },
    writeFile: {
      entry: toolCall(
        'fs.write_file',
        ({ context }) => ({
          path: 'notes/missing-vips.txt',
          content: context.missingEmails.join('\n') + '\n'
        })
      ),
      on: {
        TOOL_RESULT: 'done',
        TOOL_DENIED: 'done',
        TOOL_ERROR: 'failed'
      }
    },
    done: {
      type: 'final'
    },
    failed: {
      type: 'final'
    }
  }
});

