import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

interface Customer {
  _id: any;
  email: string;
  tier: string;
  name: string;
  city: string;
}

export default setup({}).createMachine({
  id: 'vip-processor',
  context: {
    vipEmails: [] as string[],
    currentIndex: 0,
    missingEmails: [] as string[],
    customerExists: false
  },
  initial: 'readVipFile',
  states: {
    readVipFile: {
      entry: toolCall('fs.read_file', { path: 'notes/vip.txt' }),
      on: {
        TOOL_RESULT: {
          target: 'parseEmails',
          actions: assign({
            vipEmails: ({ event }) => {
              const content = event.result as string;
              return content
                .split('\n')
                .map(line => line.trim())
                .filter(line => line && !line.startsWith('#'));
            }
          })
        },
        TOOL_ERROR: 'failed'
      }
    },
    parseEmails: {
      always: [
        {
          guard: ({ context }) => context.currentIndex < context.vipEmails.length,
          target: 'checkCustomer'
        },
        {
          target: 'writeMissingVips'
        }
      ]
    },
    checkCustomer: {
      entry: toolCall(
        'mongo.find',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.vipEmails[context.currentIndex] }
        })
      ),
      on: {
        TOOL_RESULT: {
          target: 'handleCustomer',
          actions: assign({
            customerExists: ({ event }) => {
              const result = event.result as { documents: Customer[] };
              return result.documents.length > 0;
            }
          })
        },
        TOOL_ERROR: 'failed'
      }
    },
    handleCustomer: {
      always: [
        {
          guard: ({ context }) => !context.customerExists,
          target: 'addToMissing'
        },
        {
          target: 'updateTier'
        }
      ]
    },
    addToMissing: {
      entry: assign({
        missingEmails: ({ context }) => [
          ...context.missingEmails,
          context.vipEmails[context.currentIndex]
        ],
        currentIndex: ({ context }) => context.currentIndex + 1
      }),
      always: 'parseEmails'
    },
    updateTier: {
      entry: toolCall(
        'mongo.update-many',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.vipEmails[context.currentIndex] },
          update: { $set: { tier: 'gold' } }
        })
      ),
      on: {
        TOOL_RESULT: {
          target: 'nextEmail'
        },
        TOOL_ERROR: 'failed'
      }
    },
    nextEmail: {
      entry: assign({
        currentIndex: ({ context }) => context.currentIndex + 1
      }),
      always: 'parseEmails'
    },
    writeMissingVips: {
      always: [
        {
          guard: ({ context }) => context.missingEmails.length === 0,
          target: 'done'
        },
        {
          target: 'writeFile'
        }
      ]
    },
    writeFile: {
      entry: toolCall(
        'fs.write_file',
        ({ context }) => ({
          path: 'notes/missing-vips.txt',
          content: context.missingEmails.join('\n') + '\n'
        })
      ),
      on: {
        TOOL_RESULT: 'done',
        TOOL_DENIED: 'done',
        TOOL_ERROR: 'failed'
      }
    },
    done: {
      type: 'final'
    },
    failed: {
      type: 'final'
    }
  }
});

