      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, idx) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email }
              },
