                },
                { id: 'update' + idx }
              )
            );
          });
      }),
      on: {
        TOOL_RESULT: {},
        TOOL_DENIED: {},
        TOOL_ERROR: {},
        always: {
          target: 'writeMissingVips'
        }
      }
    },
    writeMissingVips: {
      always: [
        {
          guard: ({ context }) => context.missingEmails.length === 0,
          target: 'done'
        },
        {
          target: 'writeFile'
        }
      ]
    },
    writeFile: {
      entry: toolCall(
        'fs.write_file',
