import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const nums=[146,144,142,140,139,137,12,11,135,10,134,8,132,131,128,127,125,124,123,121,120,117,116,114,113,111];
export default setup({}).createMachine({
  id:'m',
  context:{hits:[],done:0,posted:[],other:0},
  initial:'reading',
  states:{
    reading:{
      entry: enqueueActions(({enqueue})=>{nums.forEach(n=>enqueue(toolCall('github.pull_request_read',{method:'get_files',owner:'acme',repo:'widgets',pullNumber:n,perPage:100},{id:'r'+n})))}),
      on:{
        TOOL_RESULT:{actions:assign(({context,event})=>{
          let f=event.result; if(typeof f==='string'){try{f=JSON.parse(f)}catch(e){f=[]}}
          const hit=Array.isArray(f)&&f.some(x=>x.filename&&x.filename.startsWith('src/export/'));
          return {done:context.done+1,hits:hit?[...context.hits,Number(event.callId.slice(1))]:context.hits};
        })},
        TOOL_ERROR:{actions:assign({done:({context})=>context.done+1,other:({context})=>context.other+1})},
      },
      always:{guard:({context})=>context.done===nums.length,target:'writing'}
    },
    writing:{
      entry: enqueueActions(({context,enqueue})=>{context.hits.forEach(n=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:n,body:'Please add a CHANGELOG entry for the export changes.'},{id:'w'+n})))}),
      on:{
        TOOL_RESULT:{actions:assign({posted:({context,event})=>[...context.posted,event.callId]})},
        TOOL_DENIED:{actions:assign({other:({context})=>context.other+1})},
        TOOL_ERROR:{actions:assign({other:({context})=>context.other+1})},
      },
      always:{guard:({context})=>context.posted.length+context.other>=context.hits.length,target:'done'}
    },
    done:{type:'final'}
  },
  output:({context})=>context
});

