        TOOL_ERROR:{actions:assign({done:({context})=>context.done+1,other:({context})=>context.other+1})},
      },
      always:{guard:({context})=>context.done===nums.length,target:'writing'}
    },
    writing:{
      entry: enqueueActions(({context,enqueue})=>{context.hits.forEach(n=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:n,body:'Please add a CHANGELOG entry for the export changes.'},{id:'w'+n})))}),
      on:{
        TOOL_RESULT:{actions:assign({posted:({context,event})=>[...context.posted,event.callId]})},
        TOOL_DENIED:{actions:assign({other:({context})=>context.other+1})},
        TOOL_ERROR:{actions:assign({other:({context})=>context.other+1})},
      },
      always:{guard:({context})=>context.posted.length+context.other>=context.hits.length,target:'done'}
    },
    done:{type:'final'}
  },
  output:({context})=>context
});

